const body = $input.first().json.body || $input.first().json;
const valid = Boolean(
  body &&
  body.event === 'FRAUD_ALERT' &&
  body.facture &&
  body.facture.facture_id &&
  body.prediction &&
  typeof body.prediction.score_fraude === 'number' &&
  typeof body.prediction.seuil_applique === 'number'
);
return [{ json: { ...body, _valid_payload: valid } }];

const item = $input.first().json;
const f = item.facture || {};
const p = item.prediction || {};
const s = item.explicabilite_shap || {};
const a = item.liens_action || {};

const slack_text = `🚨 *ALERTE FRAUDE SANTE*\n` +
  `• *Facture* : \`${f.facture_id}\` (N° ${f.numero_facture || 'N/A'})\n` +
  `• *Prestataire* : \`${f.prestataire_id}\` | *Assuré* : \`${f.assure_id}\`\n` +
  `• *Montant Total* : ${f.montant_total} MGA (Demandé : ${f.montant_demande} MGA)\n` +
  `• *Score de Risque* : *${p.score_fraude}* (Seuil : ${p.seuil_applique}) [Modèle : \`${p.version_modele}\`]\n` +
  `• *Facteur Principal* : ${s.facteur_principal || 'N/A'}\n` +
  `• *Facteur Secondaire* : ${s.facteur_secondaire || 'N/A'}\n` +
  `👉 <${a.dashboard_url}|Accéder au dossier dans le dashboard>`;

const email_subject = `[ALERTE FRAUDE] Facture ${f.facture_id} - Score ${p.score_fraude}`;

const email_html = `<h2>🚨 Alerte Détection de Fraude - PrediCare TPA</h2>` +
  `<p>Une anomalie prioritaire a été détectée lors de la télétransmission.</p>` +
  `<ul>` +
  `<li><b>Identifiant Facture :</b> ${f.facture_id}</li>` +
  `<li><b>Numéro d'émission :</b> ${f.numero_facture || 'N/A'}</li>` +
  `<li><b>Prestataire :</b> ${f.prestataire_id}</li>` +
  `<li><b>Bénéficiaire (Assuré) :</b> ${f.assure_id}</li>` +
  `<li><b>Montant Réclamé :</b> ${f.montant_demande} MGA (Total : ${f.montant_total} MGA)</li>` +
  `<li><b>Score de Risque :</b> <span style="color:red;font-weight:bold;">${p.score_fraude}</span> (Seuil configuré : ${p.seuil_applique})</li>` +
  `<li><b>Version Modèle :</b> ${p.version_modele}</li>` +
  `<li><b>Facteur Explicatif Principal :</b> ${s.facteur_principal || 'N/A'}</li>` +
  `<li><b>Facteur Explicatif Secondaire :</b> ${s.facteur_secondaire || 'N/A'}</li>` +
  `</ul>` +
  `<p><a href="${a.dashboard_url}" style="background:#0055ff;color:#fff;padding:10px 16px;text-decoration:none;border-radius:4px;">Consulter la facture sur le Dashboard</a></p>`;

return [{
  json: {
    ...item,
    slack_text,
    email_subject,
    email_html
  }
}];
